.breath-halo {
  width: 220px;
  height: 220px;
  border-width: 1px;
  border-color: #247f96;
  border-radius: 110px;
  justify-content: center;
  align-items: center;
  background-color: #102944;
}

.breath-halo.inhale {
  animation-name: halo-inhale;
  animation-duration: 4000ms;
  animation-timing-function: ease-in-out;
  animation-iteration-count: 1;
  animation-fill-mode: forwards;
}

.breath-halo.hold {
  border-color: #67e8f9;
  animation-name: halo-hold;
  animation-duration: 2000ms;
  animation-timing-function: ease-in-out;
  animation-iteration-count: 1;
  animation-fill-mode: forwards;
}

.breath-halo.exhale {
  animation-name: halo-exhale;
  animation-duration: 4000ms;
  animation-timing-function: ease-in-out;
  animation-iteration-count: 1;
  animation-fill-mode: forwards;
}

.breath-halo.rhythm-calming.exhale {
  animation-duration: 6000ms;
}

.breath-orb {
  width: 184px;
  height: 184px;
  border-radius: 100px;
  justify-content: center;
  align-items: center;
  background-color: #163c59;
}

.breath-orb.inhale {
  background-color: #15516d;
  animation-name: orb-inhale;
  animation-duration: 4000ms;
  animation-timing-function: ease-in-out;
  animation-iteration-count: 1;
  animation-fill-mode: forwards;
}

.breath-orb.hold {
  background-color: #17647d;
  animation-name: orb-hold;
  animation-duration: 2000ms;
  animation-timing-function: ease-in-out;
  animation-iteration-count: 1;
  animation-fill-mode: forwards;
}

.breath-orb.exhale {
  background-color: #12324d;
  animation-name: orb-exhale;
  animation-duration: 4000ms;
  animation-timing-function: ease-in-out;
  animation-iteration-count: 1;
  animation-fill-mode: forwards;
}

.breath-orb.rhythm-calming.exhale {
  animation-duration: 6000ms;
}

.orb-core {
  width: 38px;
  height: 38px;
  border-radius: 19px;
  background-color: #a5f3fc;
}

.inhale-core {
  opacity: 1;
  animation-name: core-breathe;
  animation-duration: 4000ms;
  animation-timing-function: ease-in-out;
  animation-iteration-count: 1;
  animation-fill-mode: forwards;
}

.hold-core {
